    imageHint: "Dead Sea salt formations and mountain backdrop",
    descriptionAdvanced: {
      de: "Das Becken des Toten Meeres ist eine geografische Sensation und markiert mit seinem Seespiegel von rund 430 Metern unter dem Meeresspiegel den tiefsten Punkt der Erde auf dem Festland. Dieses endorheische Becken liegt im Jordangraben und ist für seine extreme Salinität bekannt, die mit etwa 33 % fast zehnmal höher ist als die der Weltmeere. Das Wasser ist so mineralstoffreich, dass es eine enorme tragende Kraft besitzt, die Schwimmer mühelos an der Oberfläche hält. Die Landschaft am Westufer ist geprägt von schroffen Kalksteinklippen und einer kargen Wüstenlandschaft, die einen dramatischen Kontrast zum tiefblauen Wasser bildet. Historisch und geologisch ist das Becken faszinierend, da es Teil des Großen Afrikanischen Grabenbruchs ist. Neben der einzigartigen Geographie ist die Region weltweit für ihre therapeutischen Schlämme und mineralhaltigen Quellen bekannt, die seit der Antike für Gesundheitsanwendungen genutzt werden.",
      hu: "A Holt-tenger medencéje a Föld egyik legkülönlegesebb földrajzi helyszíne, hiszen itt található a szárazföldi felszín legmélyebb pontja, több mint 430 méterrel a tengerszint alatt. Ez a zárt lefolyású medence a Jordán-árokban fekszik, és extrém sós vizéről vált világhírűvé. A 33%-os sókoncentráció miatt a víz sűrűsége olyan nagy, hogy az emberi test könnyedén lebeg a felszínén, miközben a vízben található ásványi anyagok gyógyító hatásukról ismertek. A nyugati partvidéket meredek mészkősziklák és sivatagi dűnék határolják, amelyek lenyűgöző látványt nyújtanak a kék víztükörrel szemben. A medence kialakulása a Nagy-Afrikai-árokrendszer mozgásaihoz köthető, így geológiai szempontból is rendkívül izgalmas terület. A térség nemcsak természeti csoda, hanem évezredek óta fontos kulturális és egészségügyi célpont is, ahol a látogatók megtapasztalhatják a sivatagi klíma és a sós pára különleges élettani hatásait.",
      ro: "Bazinul Mării Moarte este o destinație geografică fascinantă, reprezentând cel mai jos punct de pe uscatul Terrei, cu o oglindă a apei situată la aproximativ 430 de metri sub nivelul mării. Situat în depresiunea tectonică a Văii Iordanului, acest bazin este celebru pentru salinitatea sa extremă de circa 33%, care face imposibilă viața macroscopică, dar oferă o flotabilitate unică ce permite turiștilor să plutească fără efort la suprafață. Peisajul malului vestic este dominat de faleze de calcar abrupte și aride, care se prăbușesc spectaculos spre apele turcoaz, creând un contrast vizual memorabil. Regiunea are o importanță geologică imensă, fiind parte a sistemului de rift afro-arab, și este recunoscută încă din antichitate pentru proprietățile curative ale nămolurilor și sărurilor sale bogate în magneziu și potasiu. Vizitarea acestui bazin oferă o experiență multisenzorială, combinând peisajele deșertice dramatice cu beneficiile terapeutice ale apei.",
      en: "The Dead Sea Basin is a world-renowned geographical wonder, marking the lowest elevation on the Earth's land surface at approximately 430 meters below sea level. Nestled within the Jordan Rift Valley, this endorheic basin is famous for its hyper-saline waters, with a salt concentration of around 33%, nearly ten times saltier than the ocean. This extreme density allows bathers to float effortlessly on the surface, while the high mineral content of the water and mud is sought after for its therapeutic properties. The western shore is defined by dramatic limestone cliffs and stark desert landscapes that offer a stunning contrast to the deep blue of the water. Geologically, the basin is a key part of the Great Rift Valley system and continues to be a site of intense scientific study. Beyond its physical attributes, the Dead Sea Basin has been a center of human history and wellness for millennia, drawing visitors from across the globe to experience its unique environment and natural healing powers.",
      es: "La cuenca del Mar Muerto forma parte del Gran Valle del Rift y representa el punto más bajo de la superficie de la Tierra. El relieve está marcado por espectaculares laderas escarpadas y capas de sedimentos salinos depositados durante millones de años. La evaporación extrema ha creado una topografía única con salinas y sumideros.",
      pt: "A bacia do Mar Morto faz parte do Grande Vale do Rift e representa o ponto mais baixo da superfície da Terra. O relevo é caracterizado por encostas íngremes dramáticas e camadas de sedimentos salinos depositadas ao longo de milhões de anos. A evaporação extrema criou uma topografia única com salinas e buracos na terra.",
      fr: "Le bassin de la mer Morte fait partie de la grande vallée du Rift et constitue le point le plus bas de la surface terrestre. Le relief est marqué par des escarpements spectaculaires et des couches de sédiments salins déposées sur des millions d'années. L'évaporation extrême a créé une topographie unique avec des marais salants et des dolines.",
    },
    factsAdvanced: {
      de: ["Wasserspiegel liegt ca. 430 Meter unter dem Meeresspiegel", "Maximale Tiefe des Beckens erreicht ca. 300 Meter", "Salzgehalt des Wassers beträgt etwa 34 Prozent", "Beinhaltet bedeutende Vorkommen von Kali und Magnesium", "Umfasst die Halbinsel Lisan auf der östlichen Seite", "Sinkende Pegelstände führen zur Bildung von Senklöchern"],
      hu: ["A vízszint kb. 430 méterrel a tengerszint alatt van", "A medence maximális mélysége eléri a 300 métert", "A víz sótartalma körülbelül 34 százalék", "Jelentős kálium- és magnéziumlelőhelyeket tartalmaz", "Magában foglalja a keleti oldalon lévő Liszan-félszigetet", "A csökkenő vízszint miatt víznyelők alakulnak ki"],
      ro: ["Nivelul apei este la cca. 430 de metri sub nivelul mării", "Adâncimea maximă a bazinului atinge cca. 300 de metri", "Salinitatea apei este de aproximativ 34%", "Conține zăcăminte importante de potasă și magneziu", "Include peninsula Lisan pe partea estică", "Scăderea nivelului apei duce la formarea dolinelor"],
      en: ["Water level is approx. 430 meters below sea level", "Maximum basin depth reaches about 300 meters", "Water salinity is approximately 34 percent", "Contains significant deposits of potash and magnesium", "Includes the Lisan Peninsula on the eastern side", "Receding water levels lead to the formation of sinkholes"],
      es: ["El nivel del agua está unos 430 metros bajo el nivel del mar", "La profundidad máxima de la cuenca alcanza unos 300 metros", "La salinidad del agua es de aproximadamente el 34 por ciento", "Contiene importantes depósitos de potasio y magnesio", "Incluye la península de Lisán en el lado oriental", "El descenso del nivel del agua provoca la formación de sumideros"],
      pt: ["O nível da água situa-se cerca de 430 metros abaixo do nível do mar", "A profundidade máxima da bacia atinge cerca de 300 metros", "O teor de sal da água é de cerca de 34 por cento", "Contém depósitos significativos de potássio e magnésio", "Abrange a península de Lisan no lado oriental", "A descida do nível das águas leva à formação de buracos na terra"],
      fr: ["Le niveau de l'eau se situe à environ 430 mètres sous le niveau de la mer", "La profondeur maximale du bassin atteint environ 300 mètres", "La teneur en sel de l'eau est d'environ 34 %", "Contient d'importants gisements de potasse et de magnésium", "Comprend la péninsule de Lisan sur le côté est", "La baisse du niveau de l'eau entraîne la formation de dolines"],
    },
