      es: ["Forma cónica distintiva", "377 metros sobre el nivel del mar", "Antigua estación de señales", "Domina el valle del Jordán"],
      pt: ["Forma cónica distinta", "377 metros acima do nível do mar", "Antiga estação de sinais", "Domina o vale do Jordão"],
