    imageHint: "Mount Sartaba conical peak Jordan Valley",
    descriptionAdvanced: {
      de: "Der Berg Sartaba, auch als Alexandrium bekannt, ist eine der markantesten Erhebungen im Jordantal. Seine nahezu perfekte Kegelform macht ihn weithin sichtbar und zu einem natürlichen Wahrzeichen. Historisch gesehen war der Gipfel Standort einer bedeutenden hasmonäischen Festung, die von Alexander Jannäus im 1. Jahrhundert v. Chr. errichtet wurde. Neben seiner militärischen Funktion diente Sartaba in der Antike als eine der wichtigsten Signalstationen Judäas. Von hier aus wurden Freudenfeuer entzündet, um die Ankunft des Neumonds und damit den Beginn jüdischer Feiertage bis nach Babylonien zu signalisieren. Heute sind auf dem Gipfel die Überreste von Mauern, Zisternen und aufwendigen Wasserleitungssystemen zu sehen, die von der ingenieurstechnischen Leistung der damaligen Zeit zeugen. Der Aufstieg bietet einen weiten Panoramablick über das Jordantal und die gegenüberliegenden Berge von Gilead in Jordanien, was die strategische Lage dieses geschichtsträchtigen Ortes unterstreicht.",
      hu: "A Szartaba-hegy, más néven Alexandrium, a Jordán-völgy egyik leglátványosabb és legfontosabb történelmi helyszíne. A hegy szinte tökéletes kúp alakja már messziről felhívja magára a figyelmet, uralva az egyébként is drámai tájat. A csúcson találhatók Alexandrium várának romjai, amelyet I. Alexandrosz Jannaiosz hasmoneus király építtetett az i. e. 1. században. A vár nemcsak katonai erődítmény volt, hanem az ókori Júdea egyik legfontosabb fényjelző állomása is. A Misna leírása szerint innen indították azokat a jelzőtüzeket, amelyekkel hírül adták az újhold beköszöntét és az ünnepek kezdetét, a láncolat pedig egészen Babilonig ért. A romok között ma is láthatók az egykori ciszternák, monumentális falak és a kifinomult vízvezeték-rendszer maradványai, amelyek az ókori mérnöki tudásról tanúskodnak. A csúcsról lenyűgöző panoráma nyílik a Jordán-völgyre és a folyó túloldalán magasodó gileádi hegyekre.",
      ro: "Muntele Sartaba, cunoscut și sub numele de Alexandrium, este unul dintre cele mai emblematice situri istorice din Valea Iordanului. Forma sa conică aproape perfectă îl face vizibil de la distanțe mari, dominând peisajul arid al regiunii. Pe vârful muntelui se află ruinele cetății Alexandrium, construită de regele hasmonean Alexandru Jannaeus în secolul I î.Hr. Această fortăreață nu avea doar un rol militar strategic, ci servea și ca una dintre principalele stații de semnalizare prin foc din vechea Iudee. Conform tradiției, de aici se aprindeau ruguri pentru a anunța apariția Lunii Noi și începutul sărbătorilor religioase, semnalul fiind transmis din vârf în vârf până în Mesopotamia. Astăzi, vizitatorii pot vedea vestigiile zidurilor masive, sistemele ingenioase de colectare a apei și cisternele care au susținut viața pe acest vârf izolat, oferind o perspectivă unică asupra ingineriei antice și a importanței strategice a locației.",
      en: "Mount Sartaba, also known as Alexandrium, is a prominent archaeological site rising sharply above the Jordan Valley. Its distinctive conical peak served as the location for a formidable Hasmonean fortress, originally established by King Alexander Jannaeus in the 1st century BCE. Beyond its defensive capabilities, Sartaba was a vital node in the ancient Jewish communication network. According to the Mishnah, it was the second station in a chain of mountaintop signal fires used to announce the start of a new month and religious festivals, a system that extended as far as Babylonia. Excavations on the summit have revealed significant remains of masonry, massive water cisterns, and complex aqueducts that transported water up the steep slopes. The site remains a powerful symbol of regional history, offering visitors unparalleled views of the winding Jordan River and the mountains of Gilead across the border, making it a destination for history enthusiasts and hikers alike.",
      es: "El monte Sartaba es una prominente montaña aislada en el valle central del Jordán, cuyo relieve se caracteriza por laderas empinadas y una estructura de meseta en la cima. Su ubicación expuesta lo convirtió históricamente en un lugar ideal para fortificaciones y hogueras de señalización. La geología consiste principalmente en piedra caliza dura que ha resistido la erosión.",
      pt: "O monte Sartaba é uma montanha isolada proeminente no vale central do Jordão, cujo relevo se caracteriza por encostas íngremes e uma estrutura de platô no cume. A sua localização exposta tornou-o historicamente num local ideal para fortificações e fogos de sinalização. A geologia consiste predominantemente em calcário duro que resistiu à erosão.",
      fr: "Le mont Sartaba est une montagne isolée proéminente dans la vallée centrale du Jourdain, dont le relief est marqué par des pentes raides et une structure de plateau sommital plat. Sa position exposée en a fait historiquement un lieu idéal pour les fortifications et les feux de signalisation. La géologie se compose principalement de calcaire dur ayant résisté à l'érosion.",
    },
    factsAdvanced: {
      de: ["Erhebt sich etwa 650 Meter über das Niveau des Jordantals", "Gipfelplateau beherbergt Ruinen der Alexandrium-Festung", "Steile Westflanke fällt fast senkrecht ab", "Geologisch Teil der Übergangszone zum Jordangraben", "Bietet 360-Grad-Sicht bis nach Jericho und Transjordanien", "Antike Wasserzuleitungen am Hang noch sichtbar"],
      hu: ["Körülbelül 650 méterrel emelkedik a Jordán-völgy szintje fölé", "A csúcsplatón találhatók az Alexandrium erőd romjai", "Meredek nyugati oldala szinte függőlegesen szakad le", "Geológiailag a Jordán-árok felé tartó átmeneti zóna része", "360 fokos kilátás nyílik Jerikóra és Transzjordániára", "A hegyoldalon még láthatók az ókori vízvezetékek"],
      ro: ["Se ridică la aproximativ 650 de metri deasupra Văii Iordanului", "Platoul somital găzduiește ruinele cetății Alexandrium", "Flancul vestic abrupt coboară aproape vertical", "Geologic face parte din zona de tranziție către Valea Riftului", "Oferă o vedere de 360 de grade până la Ierihon și Transjordania", "Conducte antice de apă încă vizibile pe versant"],
      en: ["Rises about 650 meters above the level of the Jordan Valley", "Summit plateau hosts the ruins of Alexandrium fortress", "Steep western flank drops almost vertically", "Geologically part of the transition zone to the Jordan Rift", "Provides 360-degree views to Jericho and Transjordan", "Ancient water conduits still visible on the slopes"],
      es: ["Se eleva unos 650 metros sobre el nivel del valle del Jordán", "La meseta de la cima alberga las ruinas de la fortaleza Alexandrium", "El flanco occidental empinado cae casi verticalmente", "Geológicamente forma parte de la zona de transición a la depresión del Jordán", "Ofrece una vista de 360 grados hasta Jericó y Transjordania", "Las antiguas tuberías de agua en la ladera aún son visibles"],
      pt: ["Eleva-se cerca de 650 metros acima do nível do vale do Jordão", "O platô do cume abriga as ruínas da fortaleza Alexandrium", "O flanco ocidental íngreme desce quase verticalmente", "Geologicamente faz parte da zona de transição para a fenda do Jordão", "Oferece uma vista de 360 graus até Jericó e Transjordânia", "Antigas condutas de água na encosta ainda são visíveis"],
      fr: ["S'élève d'environ 650 mètres au-dessus du niveau de la vallée du Jourdain", "Le plateau sommital abrite les ruines de la forteresse d'Alexandrium", "Le flanc ouest escarpé descend presque verticalement", "Géologiquement fait partie de la zone de transition vers le fossé du Jourdain", "Offre une vue à 360 degrés jusqu'à Jéricho et la Transjordanie", "D'anciennes conduites d'eau sur la pente sont encore visibles"],
    },
