    name: { de: "Muntar-Hügel", hu: "Muntar-domb", ro: "Dealul Muntar", en: "Mount Muntar" },
    coords: [34.472, 31.503],
    description: {
      de: "Der Muntar-Hügel ist die höchste Erhebung in der Nähe der Stadt Gaza. Er bietet einen strategischen Blick über die gesamte Küstenebene und den Hafen.",
      hu: "A Muntar-domb a Gáza városa melletti legmagasabb pont. Stratégiai kilátást nyújt a teljes tengerparti síkságra és a kikötőre.",
      ro: "Dealul Muntar este cea mai înaltă cotă din apropierea orașului Gaza. Oferă o perspectivă strategică asupra întregii câmpii litorale.",
      en: "Mount Muntar is the highest elevation near Gaza City. It offers a strategic view over the entire coastal plain and the harbor.",
      es: "La colina de Muntar es la elevación más alta cerca de la ciudad de Gaza. Ofrece una vista estratégica de toda la llanura costera y el puerto.",
      pt: "A colina de Muntar é a elevação mais alta perto da cidade de Gaza. Oferece uma vista estratégica de toda a planície costeira e do porto.",
      fr: "La colline de Muntar est la plus haute élévation près de la ville de Gaza. Elle offre une vue stratégique sur toute la plaine côtière et le port.",
    },
    facts: {
      de: ["Höchster Punkt bei Gaza", "80 Meter über NN", "Strategischer Beobachtungspunkt", "Teil eines Kurkar-Rückens"],
      hu: ["Gáza legmagasabb pontja", "80 méter tengerszint felett", "Stratégiai megfigyelőhely", "Egy kurkar-hátság része"],
      ro: ["Cel mai înalt punct din Gaza", "Altitudine de 80 metri", "Observator strategic istoric", "Format pe o creastă de kurkar"],
      en: ["Highest point in Gaza City", "80 meters above sea level", "Historic strategic observer", "Part of a kurkar ridge"],
      es: ["Punto más alto cerca de Gaza", "80 metros sobre el nivel del mar", "Punto de observación estratégico", "Parte de una cresta de kurkar"],
      pt: ["Ponto mais alto perto de Gaza", "80 metros acima do nível do mar", "Ponto de observação estratégico", "Parte de uma crista de kurkar"],
      fr: ["Point culminant près de Gaza", "80 mètres au-dessus du niveau de la mer", "Point d'observation stratégique", "Fait partie d'une crête de kurkar"],
    },
    imageHint: "Mount Muntar hill overlooking Gaza City",
    descriptionAdvanced: {
      de: "Der Muntar-Hügel, im Osten der Stadt Gaza gelegen, ist die höchste natürliche Erhebung der Küstenebene und ein Ort von großer strategischer und historischer Bedeutung. Mit einer Höhe von etwa 80 Metern über dem Meeresspiegel bietet er einen ungestörten Rundumblick über die Stadt Gaza, den Hafen und weit in das Hinterland hinein. Der Hügel besteht geologisch aus 'Kurkar', einer für diese Region typischen Art von versteinerten Sanddünen. Aufgrund seiner dominierenden Lage war der Muntar-Hügel im Laufe der Jahrhunderte Schauplatz zahlreicher militärischer Auseinandersetzungen, darunter bedeutende Schlachten während des Ersten Weltkriegs, als britische Truppen um die Kontrolle über Gaza kämpften. Der Name 'Muntar' bedeutet im Arabischen 'Beobachtungsposten', was seine historische Funktion perfekt beschreibt. Neben seiner militärischen Geschichte ist der Hügel auch ein Ort mit religiöser Bedeutung und war in der Vergangenheit Ziel traditioneller Pilgerreisen. Von hier aus lässt sich die geografische Ausdehnung des Gazastreifens und die Nähe zum Mittelmeer besonders eindrucksvoll erfassen, was den Hügel zu einem der markantesten geografischen Orientierungspunkte der Region macht.",
      hu: "A Muntar-domb Gáza várostól keletre emelkedik, és a tengerparti síkság legmagasabb pontjaként kiemelkedő stratégiai jelentőséggel bír. A mindössze 80 méteres tengerszint feletti magassága ellenére a domb uralja a környező tájat, lehetővé téve a teljes gázai kikötő és a belváros megfigyelését. Geológiailag a domb a térségre jellemző 'kurkar' (megkövült homokdűne) hátság része, amely ellenállóbb a környező puha talajnál. Történelme során számos konfliktus tanúja volt; itt zajlottak az első világháború döntő gázai csatái 1917-ben, amikor az oszmán és a brit erők küzdöttek a magaslat birtoklásáért. A 'Muntar' név arabul 'figyelőhelyet' jelent, ami híven tükrözi évezredes funkcióját. A helyi hagyományban a domb vallási tisztelet övezte helyszín is volt, ahol népi fesztiválokat tartottak. Ma a domb a város növekedésének és a tengerparti síkság földrajzi tagoltságának egyik legfontosabb tájékozódási pontja, ahonnan tiszta időben messzire el lehet látni a Földközi-tenger irányába és a szárazföld belseje felé is.",
      ro: "Dealul Muntar, situat în partea de est a orașului Gaza, reprezintă cea mai înaltă cotă naturală a regiunii și un punct de referință strategic major de-a lungul istoriei. Deși are o altitudine modestă de aproximativ 80 de metri, poziția sa dominantă deasupra câmpiei litorale oferă o vizibilitate panoramică excepțională asupra întregii zone urbane, a portului și a hinterlandului agricol. Geologic, dealul face parte dintr-o creastă de 'kurkar' – un tip de gresie formată din dune de nisip fosilizate, specifică coastei mediteraneene de est. Numele său, care în limba arabă înseamnă 'loc de veghe' sau 'observator', reflectă utilitatea sa militară seculară. Aici s-au purtat lupte grele în timpul Primului Război Mondial, când armata britanică a încercat să cucerească Gaza de la forțele otomane. Pe lângă valoarea sa strategică, Dealul Muntar a fost istoric un loc de pelerinaj și sărbătoare pentru localnici, fiind asociat cu tradiții religioase vechi. Astăzi, rămâne un simbol al geografiei locale, oferind o perspectivă unică asupra densității urbane a orașului Gaza și a liniei țărmului mediteranean.",
      en: "Mount Muntar, rising to the east of Gaza City, is the highest natural elevation in the coastal plain and a site of profound strategic and historical importance. Standing at approximately 80 meters above sea level, it commands an unobstructed view of the entire Gaza harbor, the urban center, and the surrounding agricultural lands. Geologically, the hill is part of a kurkar ridge—a unique formation of fossilized sandstone dunes typical of the Levantine coast. Due to its vantage point, Mount Muntar has been a focal point of military operations for centuries, most notably during the Battles of Gaza in World War I, when Allied and Ottoman forces fought fiercely for control of its heights. The Arabic name 'Muntar' translates directly to 'Watchtower,' underscoring its historical role as a primary lookout post. Historically, it was also a place of spiritual gathering, hosting traditional festivals and shrines. Today, despite urban encroachment, the hill remains the most significant geographical landmark in the Gaza Strip, offering a clear visual understanding of the region's topography and its proximity to the Mediterranean Sea.",
      es: "El monte Muntar, también conocido como el monte Azazel, es una elevación prominente en el desierto de Judea, al este de Jerusalén. Su relieve está marcado por la típica erosión árida del cinturón desértico con wadis empinados y crestas áridas. Ofrece una vista amplia sobre el desierto hasta el Mar Muerto y las montañas de Moab.",
      pt: "O monte Muntar, também conhecido como monte Azazel, é uma elevação proeminente no deserto da Judeia, a leste de Jerusalém. O seu relevo é marcado pela típica erosão árida da cintura desértica, com uádis íngremes e cristas áridas. Oferece uma vista ampla sobre o deserto até ao Mar Morto e às montanhas de Moab.",
      fr: "Le mont Muntar, également connu sous le nom de mont Azazel, est une élévation proéminente du désert de Judée, à l'est de Jérusalem. Son relief est marqué par l'érosion aride typique de la zone désertique avec des oueds escarpés et des crêtes dénudées. Il offre une vue imprenable sur le désert jusqu'à la mer Morte et les montagnes de Moab.",
    },
