    parent: "PS",
    type: "mountain",
    name: { de: "Berg Salman", hu: "Szalman-hegy", ro: "Muntele Salman", en: "Mount Salman" },
    coords: [35.232, 32.185],
    description: {
      de: "Der Berg Salman ist eine Erhebung westlich von Nablus. Er ist Teil des zentralen Samarien-Massivs und bekannt für seine felsigen Gipfelbereiche.",
      hu: "A Szalman-hegy Náplusztól nyugatra fekvő magaslat. A központi szamáriai masszívum része, és sziklás csúcsterületeiről ismert.",
      ro: "Muntele Salman este o înălțime situată la vest de Nablus. Face parte din masivul central al Samariei și este cunoscut pentru zonele sale somitale stâncoase.",
      en: "Mount Salman is an elevation located west of Nablus. It is part of the central Samarian massif and is known for its rocky summit areas.",
      es: "El monte Salman es una elevación al oeste de Nablus. Forma parte del macizo central de Samaria y es conocido por sus zonas de cumbres rocosas.",
      pt: "O monte Salman é uma elevação a oeste de Nablus. Faz parte do maciço central da Samaria e é conhecido pelas suas zonas de cumes rochosos.",
      fr: "Le mont Salman est une élévation à l'ouest de Naplouse. Il fait partie du massif central de Samarie et est connu pour ses sommets rocheux.",
    },
    facts: {
      de: ["750 Meter hohe Erhebung", "Westlich von Nablus", "Teil des Samarien-Massivs", "Felsiges Gipfelrelief"],
      hu: ["750 méter magas hegy", "Náplusztól nyugatra", "A Szamáriai-masszívum része", "Sziklás csúcsdomborzat"],
      ro: ["Altitudine de 750 metri", "Situat la vest de Nablus", "Parte a masivului Samaria", "Relief stâncos la vârf"],
      en: ["Elevation of 750 meters", "Located west of Nablus", "Part of the Samarian massif", "Rocky summit relief"],
      es: ["Elevación de 750 metros de altura", "Al oeste de Nablus", "Parte del macizo de Samaria", "Relieve de cumbre rocosa"],
      pt: ["Elevação de 750 metros de altura", "A oeste de Nablus", "Parte do maciço da Samaria", "Relevo de cume rochoso"],
      fr: ["Élévation de 750 mètres de haut", "À l'ouest de Naplouse", "Fait partie du massif de Samarie", "Relief sommital rocheux"],
    },
    imageHint: "Mount Salman rocky peak in central Samaria",
    descriptionAdvanced: {
      de: "Der Berg Salman, eine markante Erhebung im zentralen Samarien-Massiv, liegt westlich der historischen Stadt Nablus und bietet weite Ausblicke über das palästinensische Hochland. Mit einer Höhe von etwa 750 Metern über dem Meeresspiegel ist er Teil einer Gebirgskette, die das Rückgrat des nördlichen Westjordanlandes bildet. Das Relief ist geprägt durch schroffe Kalksteinfelsen und steile Hänge, die nur spärlich mit mediterraner Flora bewachsen sind. Trotz der rauen Gipfelbereiche finden sich in den tieferen Lagen und Tälern rund um den Berg Salman jahrhundertealte Olivenhaine, die von der langen landwirtschaftlichen Tradition der Region zeugen. Geologisch besteht das Massiv hauptsächlich aus Karstgestein, was zur Bildung von Höhlen und natürlichen Quellen führt, die für die Wasserversorgung der umliegenden Dörfer essenziell sind. Der Berg ist nicht nur ein geographischer Orientierungspunkt, sondern auch ein Ort von kultureller Bedeutung, da er die typische Terrassenlandschaft Palästinas überblickt. Wanderungen in diesem Gebiet erfordern Trittsicherheit, belohnen jedoch mit einer tiefen Einsicht in die geologische Struktur und die stille Schönheit des samarischen Berglandes.",
      hu: "A Szalman-hegy Náplusztól nyugatra magasodó, 750 méter magas csúcs, amely a központi Szamáriai-masszívum egyik meghatározó eleme. A hegy domborzatát a palesztin felföldre jellemző sziklás, karsztos mészkőalakzatok és meredek hegyoldalak alkotják. Ez a vidék történelmileg és földrajzilag is fontos része a régiónak, hiszen a hegytetőről belátható az egész környék, a teraszos művelésű völgyektől kezdve a távoli településekig. A növényzetet főként szárazságtűrő cserjék és gyógynövények alkotják, míg a lankásabb részeken az ősi olajfaligetek dominálnak, amelyek a helyi gazdaság alapját jelentik. A hegy geológiai felépítése különleges; a mészkőben keletkező természetes repedések és barlangok a múltban gyakran szolgáltak menedékként. A Szalman-hegy környezete ideális a természetjárók számára, akik a kopár, sziklás csúcsok és a termékeny völgyek közötti kontrasztot keresik. A csúcsról nyíló panoráma nemcsak földrajzi élményt nyújt, hanem segít megérteni a régió stratégiai és kulturális jelentőségét is a történelem folyamán.",
      ro: "Muntele Salman este o proeminență geografică situată la vest de Nablus, făcând parte din masivul muntos central al Samariei. Cu o altitudine de 750 de metri, acesta domină peisajul înconjurător prin versanții săi abrupți și crestele stâncoase formate preponderent din calcar. Relieful accidentat este tipic pentru zonele înalte ale Palestinei, unde eroziunea carstică a modelat numeroase formațiuni deosebite de-a lungul mileniilor. Vegetația este una de tip mediteranean montan, cu arbuști rezistenți la secetă și plante aromatice ce cresc printre fisurile stâncilor. La baza muntelui, pe terasele amenajate cu grijă de generații de agricultori, se întind livezi de măslini care reprezintă simbolul rezilienței locale. Muntele Salman nu este doar un obiectiv geologic, ci și un punct strategic de observație, oferind o panoramă vastă asupra văilor din Samaria și a orașului Nablus. Importanța sa este întărită de prezența unor izvoare naturale în împrejurimi, vitale pentru comunitățile rurale din zonă. Pentru cei care explorează regiunea, muntele oferă o perspectivă autentică asupra geografiei aspre, dar spectaculoase, a Cisiordaniei centrale.",
      en: "Mount Salman is a prominent elevation located west of Nablus, forming an integral part of the central Samarian massif in Palestine. Reaching a height of approximately 750 meters, the mountain is characterized by its rugged, rocky terrain and steep limestone slopes typical of the highland relief. The summit areas are predominantly stark and windswept, featuring karst formations and sparse Mediterranean vegetation. However, the lower slopes are often terraced and adorned with ancient olive groves, showcasing the region's enduring agricultural heritage. Geologically, Mount Salman is composed of layers of limestone and dolomite, which contribute to the area's complex groundwater systems and local springs. The mountain serves as a significant geographical landmark, offering expansive views over the surrounding valleys and the historic city of Nablus. Its elevation provides a cooler climate compared to the Jordan Valley, supporting a variety of hardy flora. For hikers and geographers, Mount Salman presents an opportunity to study the folded mountain structures of the region while experiencing the quiet, enduring beauty of the Samarian highlands.",
      es: "El monte Salman se encuentra en el centro de Cisjordania, al sur de Nablus. Pertenece a las tierras altas de Samaria y es conocido por su ubicación estratégica que domina las principales rutas de transporte de la región. El entorno está marcado por una mezcla de tierras agrícolas y rocas calizas escarpadas.",
      pt: "O monte Salman situa-se na Cisjordânia central, ao sul de Nablus. Pertence às terras altas da Samaria e é conhecido pela sua localização estratégica que domina as principais rotas de transporte da região. A área envolvente é marcada por uma mistura de terrenos agrícolas e rochas calcárias escarpadas.",
      fr: "Le mont Salman est situé dans le centre de la Cisjordanie, au sud de Naplouse. Il appartient aux hautes terres de Samarie et est connu pour sa position stratégique surplombant les principaux axes de transport de la région. Les environs sont marqués par un mélange de terres agricoles et de roches calcaires escarpées.",
    },
